/// Dart API for libmicnote, the Micnote host core (core/ in the repo).
///
/// The raw bindings in src/bindings.dart are generated by ffigen; this file
/// wraps them in plain Dart types for the app.
library;

import 'package:ffi/ffi.dart';

import 'src/bindings.dart' as bindings;

/// libmicnote's version, "MAJOR.MINOR.PATCH".
String coreVersion() => bindings.mn_version().cast<Utf8>().toDartString();
